[
  {
    "name": "沈青鸢",
    "description": "女主，江湖剑客，十年磨一剑只为今夜复仇的孤女",
    "appearance": "二十四岁清瘦女子，眉如远山含霜，眼眸冷冽如古井寒星，左眉尾一道极淡疤痕，发髻高绾插一支素银剑簪",
    "costume": "月白色窄袖束腰剑客服，外罩水墨灰青薄氅衣，腰悬三尺青锋剑，靴面溅有旧血痕",
    "personality": "沉默寡言、冷静如冰、内心压抑十年丧父之痛，意志如铁，出剑果决无情"
  },
  {
    "name": "顾掌柜",
    "description": "客栈老板，十年前血案知情者，本集关键配角",
    "appearance": "五十出头消瘦男子，灰白鬓发，眼窝深陷，常年含笑却笑不达眼底",
    "costume": "藏青色对襟长衫，腰系玄色布带，袖口微微卷起，指节粗糙",
    "personality": "圆滑世故、城府极深、表面殷勤内心惊惧"
  },
  {
    "name": "黑衣刺客甲",
    "description": "仇人派驻客栈的暗哨，本集反派配角",
    "appearance": "三十岁左右魁梧男子，面罩黑巾只露双眼，眼神阴鸷",
    "costume": "玄色夜行紧身衣，腰缠软索，背后斜插两柄短刃",
    "personality": "警觉狠辣、出手致命"
  }
]

[
  {
    "name": "青石山道",
    "description": "客栈外群山环抱的蜿蜒古道，沈青鸢独行赴约之路",
    "visualStyle": "雨夜浓雾，松涛呜咽，远处一盏孤灯如豆，墨蓝山影层叠，留白水墨意境"
  },
  {
    "name": "断肠客栈·外景",
    "description": "破旧黑檐客栈孤悬山腰，匾额半朽，十年风霜未改",
    "visualStyle": "暴雨倾泻如瀑，檐角挂满水帘，屋内昏黄灯火摇曳映出血色窗花，哥特式东方阴森"
  },
  {
    "name": "断肠客栈·大堂",
    "description": "空旷陈旧厅堂，歪斜桌椅散落，空气浮尘被雨湿气浸透",
    "visualStyle": "烛火昏黄惨淡如鬼火，墙上蛛网密布，角落里一坛老酒静默，木质纹理在暗光下显出年代感"
  },
  {
    "name": "断肠客栈·二楼回廊",
    "description": "木质楼廊吱呀作响，雕花木栏残缺，雨从破瓦滴落",
    "visualStyle": "阴影交错如棋盘，一盏残灯映出沈青鸢清冷侧影，地面湿滑反光"
  }
]

{
  "scenes": [
    {
      "location": "青石山道",
      "time": "深夜雨夜",
      "characters": [
        "沈青鸢"
      ],
      "action": "沈青鸢孤身撑伞独行于暴雨山道，远处客栈孤灯隐现",
      "dialogue": "",
      "mood": "孤寂肃杀，如赴一场十年之约"
    },
    {
      "location": "断肠客栈·大堂",
      "time": "深夜",
      "characters": [
        "沈青鸢",
        "顾掌柜"
      ],
      "action": "沈青鸢推门而入，滴水惊四座。顾掌柜笑容迎客，刻意掩饰紧张",
      "dialogue": "顾掌柜：客官，您是打尖还是住店？沈青鸢：住店。十年前那个位置，还空着么？",
      "mood": "暗流涌动，平静表象下危机四伏"
    },
    {
      "location": "断肠客栈·大堂",
      "time": "深夜",
      "characters": [
        "沈青鸢",
        "顾掌柜"
      ],
      "action": "顾掌柜递茶，手指微颤。沈青鸢冷眼观察",
      "dialogue": "沈青鸢：顾掌柜这双手抖得，倒像是头一回见生客。",
      "mood": "试探与反试探的猫鼠博弈"
    },
    {
      "location": "断肠客栈·二楼回廊",
      "time": "深夜",
      "characters": [
        "沈青鸢"
      ],
      "action": "沈青鸢上楼巡查，发觉角落暗哨微响",
      "dialogue": "",
      "mood": "猎手本能苏醒，屏息待发"
    },
    {
      "location": "断肠客栈·二楼回廊",
      "time": "深夜",
      "characters": [
        "沈青鸢",
        "黑衣刺客甲"
      ],
      "action": "沈青鸢拔剑出鞘，黑衣刺客自暗处暴起。两人于窄廊激战",
      "dialogue": "黑衣刺客甲：找死！",
      "mood": "骤然爆发的凌厉杀意，剑光如电"
    },
    {
      "location": "断肠客栈·大堂",
      "time": "深夜",
      "characters": [
        "沈青鸢",
        "顾掌柜"
      ],
      "action": "沈青鸢将染血刺客掷于掌柜面前，逼问仇人下落",
      "dialogue": "沈青鸢：十年前那桩血案，主家是谁。说。",
      "mood": "冷若冰霜的威压，十年怒火一朝喷薄"
    }
  ]
}
